SELECT gtin, name, pack, case_units, flow, price_inr, cost_inr 
FROM store.products 
LIMIT 20;

SELECT COUNT(*) AS upi_refunds_june_2026
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT sku, name, pack, case_kg 
FROM store.products 
WHERE LOWER(name) LIKE '%atta%' OR LOWER(pack) LIKE '%atta%';

SELECT complaint_ts, kind, resolution, bill_id 
FROM store.customer_complaints 
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';
